      '<div class="e1-docpage' + (toc ? ' has-toc' : '') + '"><div class="e1-docpage__main">' + o.body + stamp(o.stamp || o.title) + '</div>' + (toc ? '<aside class="e1-docpage__toc">' + toc + '</aside>' : '') + '</div>';
