  function link(label, href) { return '<a href="' + esc(href) + '">' + esc(label) + '</a>'; }
  function go(label, href) { return '<a class="rr-go" href="' + esc(href) + '">' + esc(label) + c.icon('arrow-right', 14) + '</a>'; }
