  /* Live filter helper for lists rendered client-side. */
  function wireFilter(el, o) {
    var input = el.querySelector(o.input); if (!input) return;
    function apply() {
      var q = (input.value || '').trim().toLowerCase(), shown = 0, total = 0;
      el.querySelectorAll(o.items).forEach(function (it) {
        total++;
        var extra = o.extra ? o.extra(it) : true;
        var ok = (o.always && o.always(it)) || extra && (!q || (it.getAttribute('data-text') || it.textContent.toLowerCase()).indexOf(q) >= 0);
        it.classList.toggle('rr-hidden', !ok); if (ok) shown++;
      });
      var none = el.querySelector(o.none); if (none) none.classList.toggle('is-on', shown === 0);
      var cnt = el.querySelector(o.count); if (cnt) cnt.textContent = shown === total ? (total + ' shown') : (shown + ' of ' + total + ' shown');
      if (o.groups) o.groups(el);
      if (o.key) setQuery(o.key, input.value.trim());
    }
    input.addEventListener('input', apply);
    apply();
    return apply;
  }

