  RD.quadrants = {
    1: { label: 'Documentation × model-centric', note: 'Registers, questionnaires and model risk. The record is a document about the AI.' },
    2: { label: 'Enforcement × model-centric', note: '“The unit is a model interaction, so the record is a trace.”' },
    3: { label: 'Action-centric, not enforced', note: 'Agents act on business records with no gate, or a book of record with no agent yet.' },
    4: { label: 'Enforcement × action · single vendor', note: '“Right unit, right position in the path, locked to one estate.”' }
  };

  RD.findings = [
    ['Almost nobody governs the business write.', 'Across both batches the central object is a use case, a model, an asset, an identity or a data flow. Palantir is the only product whose screens are drawn around the action — Input → Rules → Submission criteria → History — and only on Foundry objects.'],
    ['The console grammar has converged, so elan1 must look familiar.', 'KPI tiles, then a risk donut or gauge, then an inventory with state and status pills, then a record page with tabs and a review side panel. Nobody opening elan1 should meet an unfamiliar layout; the difference is that every tile counts writes and gaps, not AI assets.'],
    ['“Enforcement” moved in 2026, but it stops at the model, the gateway or the identity.', 'ServiceNow (kill switch, AI Gateway, GA Aug 2026), Boomi (approval hold, 2 Sep 2026 [unverified]), Airia (Agent Constraints with human-review escalation), ModelOp + Kong (endpoint allow/deny), Microsoft (block at identity). None shows a record of the business write, and none shows a signed or chained artefact.'],
    ['Refusals are counted, not recorded.', 'Palantir shows failure types in metrics, OneTrust counts “blocked, redacted, routed”, Boomi counts errors. No product has a page for one refused action with its reason, its policy and its evidence. That page is the most distinctive screen elan1 can ship.'],
    ['The “independently checkable” column is empty for every vendor — elan1 included.', 'Cranium shares an “AI Card” score through trust hubs and now says “automated attestation”; it is vendor-asserted. Sigstore Rekor, a benchmark rather than a competitor, shows what a login-free public verifier looks like.'],
    ['Inventory is being given away.', 'SAP includes AI Agent Hub at no additional cost; Microsoft bundles Agent 365 in E7; ServiceNow sells Control Tower inside its platform. elan1 is never pitched as an agent inventory — it is the proof of each business write, checkable without us.']
  ];

  RD.lines = [
    ['A model may produce a write intent. It may never produce an allow.', 'Information Memorandum §4.1 — the sentence the company leads with, true at L1 without a signature.'],
    ['The industry signs what an agent was allowed to do, and does not sign what it did.', 'IM §3.3, §12.4 · O12'],
    ['Airia and Zenity tell security what an agent tried. elan1 gives finance and the auditor a receipt for what was written, or refused.', 'Batch 2 §5'],
    ['ModelOp decides and Kong enforces. elan1 decides, gates and seals in one hop, per record, not per endpoint.', 'Batch 2 §5'],
    ['SAP, Microsoft and ServiceNow give you an agent inventory for free. elan1 is not an inventory.', 'Batch 2 §5'],
    ['Cranium shares a score. elan1 shares something you can verify.', 'Batch 2 §5 · the verify claim is an L2 claim; at L1 “verify requires us”'],
    ['Open Policy Agent signs the policy bundle. It does not sign the decision.', 'E08 §04']
  ];

  /* Cross-vendor UX patterns: [pattern, seen in (slugs), verdict, note] */
  RD.patterns = [
    ['KPI tile row + risk donut or gauge + inventory table', ['credo-ai', 'servicenow-ai-control-tower', 'ibm-watsonx-governance', 'microsoft-agent-365', 'boomi-agent-control-tower', 'holistic-ai'], 'Match', 'The baseline users expect. elan1 tiles count writes and gaps, not AI assets.', '#/work/today'],
    ['Record header: ID + stage chip + status chip + one primary CTA', ['credo-ai', 'microsoft-agent-365', 'palantir-aip'], 'Match', 'On every elan1 record: proof sequence, outcome, level, one action.', '#/records/object/SINV-2026-01187'],
    ['Lifecycle state kept apart from review status', ['servicenow-ai-control-tower', 'credo-ai'], 'Match', 'For a write: state (proposed · held · executed · reverted) and decision (allowed · approved · refused).', '#/work/writes/w_8c21'],
    ['“Top items / top actions for you” work queue', ['servicenow-ai-control-tower', 'microsoft-agent-365'], 'Match', 'It is the home of the Work door: Today → Needs you.', '#/work/today'],
    ['Review side panel (reviewers N/M signed off, due date, comments)', ['credo-ai', 'ibm-watsonx-governance'], 'Match and extend', 'Bound to one pending write with its business diff.', '#/work/decide/OB-2026-0412'],
    ['Right-hand flyout from a table row', ['microsoft-agent-365', 'servicenow-ai-control-tower', 'noma'], 'Match', 'Records and Agents open a drawer without leaving the list.', '#/agents/registry'],
    ['Risk-based routing lanes with SLAs', ['trustible'], 'Adopt', 'Auto-allow / single approver / dual approval, each with a countdown.', '#/work/approvals/arrives'],
    ['Questions as widget titles', ['onetrust-ai-governance'], 'Adopt', 'Assurance widgets are titled with questions an auditor would ask.', '#/assurance'],
    ['Change feed and propagation', ['saidot', 'onetrust-ai-governance'], 'Adopt', '“Policy v7 changed, so 3 agents need re-approval.”', '#/records/declarations/erp.ar/compare'],
    ['Rules / submission-criteria graph per action', ['palantir-aip'], 'Adopt, in plain English', 'elan1’s core screen: Input → Policy → Decision → Write → Proof.', '#/assurance/proof/4101/path'],
    ['Verb-grouped doors (Discover · Secure · Govern · Optimize; ACT · OBSERVE · MANAGE · COMPLY)', ['airia', 'relyance'], 'Match', 'Proves that verb doors scale — and why a buyer could confuse Airia with elan1.', '#/reference/ia'],
    ['Three-way decision donut (write / do not write / human review)', ['monitaur'], 'Adopt', 'Committed · Not done · Waiting on a person, with refusals given equal weight.', '#/assurance/refusals'],
    ['Discovery inbox (Action needed / Linked / Rejected)', ['sap', 'holistic-ai'], 'Adopt', 'Every agent seen at the MCP boundary lands as undeclared: Declare, Block or Link.', '#/agents/discovered'],
    ['Review-before-publish bar with plain-bullet effects', ['crator'], 'Adopt', 'The template for the approval card.', '#/work/decide/OB-2026-0412'],
    ['Composite scores (AAGEI radar, trust %, AI Card ring)', ['boomi-agent-control-tower', 'holistic-ai', 'cranium', 'truyo'], 'Avoid', 'An auditor cannot defend them. Show plain counts that open their records.', '#/assurance/coverage'],
    ['Tab rows of eight to ten', ['servicenow-ai-control-tower', 'microsoft-agent-365'], 'Avoid', 'Four doors, and at most four to five tabs per record.', '#/reference/ia'],
    ['Empty or zero dashboards', ['ibm-watsonx-governance'], 'Avoid', 'Default to the latest governed writes; every empty state names what would fill it.', '#/reference/patterns'],
    ['Refusal shown as a failure count', ['palantir-aip', 'onetrust-ai-governance', 'boomi-agent-control-tower'], 'Beat it', 'Each refusal gets its own openable record, neutral in tone, with rule, numbers and one action.', '#/work/not-done/4108']
  ];

